DO $$ BEGIN COMMENT ON TABLE recording.recording IS 'Canonical recording / TDO (Temporal Data Object) header row — one row per recording ingested or created in aiWARE. Carries identity (recording_id text PK, application_id, source_id, scheduled_job_id, organization_id), visibility (is_public), the lifecycle time-window (created_date_time, modified_date_time, start_date_time, stop_date_time — all timestamp with time zone), and a jsonb json payload carrying the full TDO document (engine results, asset refs, status flags). This is the head of the TDO write-path — TDO create/update/delete in aiware-core resolves to writes on this table plus recording_metadata/recording_clone__tdo/recording__source.'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
