DO $$ BEGIN COMMENT ON TABLE recording.recording_metadata IS 'Side table for recording.recording carrying typed metadata attached to a recording. One row per (recording_id, type) pair: type (text) discriminates the metadata flavor (ACL, schema, app-specific blob), content (jsonb) is the payload. The aiware-core DAL reads this in TDO ACL hydration (rmacl-aliased joins where type=''acl'').'; EXCEPTION WHEN OTHERS THEN NULL; END; $$;
